#[no_mangle]
pub unsafe extern "C" fn nesterov_accelerated_sgd(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<4{return -1}let wi=*v;let si=*v.add(1);let lm=*v.add(2);let mm=*v.add(3);if !(1..=8).contains(&wi)||!(1..=8).contains(&si)||!(0..=1000).contains(&lm)||!(0..=1000).contains(&mm)||n!=4+wi as usize*(si as usize+1){return -1}let w=wi as usize;let s=si as usize;let vals=std::slice::from_raw_parts(v,n);if vals[4..].iter().any(|x|!(-10000..=10000).contains(x)){return -1}if out.is_null()||cap<w*8{return -2}let mut p=[0.0f64;8];let mut vel=[0.0f64;8];for i in 0..w{p[i]=vals[4+i] as f64/1000.0}let lr=lm as f64/1000.0;let m=mm as f64/1000.0;for t in 0..s{for i in 0..w{let prev=vel[i];let g=vals[4+w+t*w+i] as f64/1000.0;vel[i]=m*vel[i]-lr*g;p[i]=p[i]-m*prev+(1.0+m)*vel[i];}}for i in 0..w{let b=p[i].to_le_bytes();for k in 0..8{*out.add(i*8+k)=b[k]}}(w*8) as i64}
